#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;
use Cwd 'abs_path';

my $repo = '/bench/repo';
my $module = 'github.com/usememos/memos';

# --- strip Go comments and strings (best-effort) ---
sub strip_go_source {
    my ($src) = @_;
    my $out = '';
    my $i = 0;
    my $len = length($src);
    while ($i < $len) {
        # line comment
        if (substr($src, $i, 2) eq '//') {
            while ($i < $len && substr($src, $i, 1) ne "\n") { $i++; }
            next;
        }
        # block comment
        if (substr($src, $i, 2) eq '/*') {
            $i += 2;
            while ($i < $len - 1 && substr($src, $i, 2) ne '*/') { $i++; }
            $i += 2 if $i < $len - 1;
            next;
        }
        # raw string
        if (substr($src, $i, 1) eq '`') {
            $out .= '`';
            $i++;
            while ($i < $len && substr($src, $i, 1) ne '`') { $i++; }
            $out .= '`' if $i < $len;
            $i++ if $i < $len;
            next;
        }
        # double-quoted string
        if (substr($src, $i, 1) eq '"') {
            $out .= '"';
            $i++;
            while ($i < $len) {
                my $c = substr($src, $i, 1);
                if ($c eq '\\') { $out .= $c; $i++; $out .= substr($src, $i, 1) if $i < $len; $i++; next; }
                $out .= $c;
                $i++;
                last if $c eq '"';
            }
            next;
        }
        # rune literal
        if (substr($src, $i, 1) eq "'") {
            $out .= "'";
            $i++;
            while ($i < $len) {
                my $c = substr($src, $i, 1);
                if ($c eq '\\') { $out .= $c; $i++; $out .= substr($src, $i, 1) if $i < $len; $i++; next; }
                $out .= $c;
                $i++;
                last if $c eq "'";
            }
            next;
        }
        $out .= substr($src, $i, 1);
        $i++;
    }
    return $out;
}

# --- collect all .go files ---
my @all_go_files;
find(sub {
    return unless /\.go$/;
    return if $File::Find::name =~ m{/vendor/};
    return if $File::Find::name =~ m{/proto/gen/};
    push @all_go_files, $File::Find::name;
}, $repo);

# --- parse package and imports from file ---
sub parse_file_meta {
    my ($path, $content) = @_;
    my $pkg = '';
    my %imports;  # alias -> full path
    my $default_import = '';

    if ($content =~ /^package\s+(\w+)/m) {
        $pkg = $1;
    }

    # single import
    while ($content =~ /\bimport\s+"([^"]+)"/g) {
        my $p = $1;
        my $alias = (split /::/, $p)[-1];
        $alias =~ s{.*/}{};
        $imports{$alias} = $p;
        $default_import = $p unless $default_import;
    }
    # grouped imports
    while ($content =~ /\bimport\s*\((.*?)\)/gs) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s{//.*}{};
            next if $line =~ /^\s*$/;
            if ($line =~ /^\s*(?:(\w+)\s+)?"([^"]+)"/) {
                my ($alias, $path) = ($1, $2);
                $alias //= (split /::/, $path)[-1];
                $alias =~ s{.*/}{};
                $imports{$alias} = $path;
            }
        }
    }

    return ($pkg, \%imports);
}

# --- extract declarations from internal/ files ---
# symbol key: "import_path|symbol_name" where symbol_name may be "(*Type).Method" or "Func"
my %decls;  # key -> { file, line, pkg, name, recv, exported, qual_name }

for my $path (@all_go_files) {
    next unless $path =~ m{/internal/};
    open my $fh, '<', $path or die $!;
    my $raw = do { local $/; <$fh> };
    close $fh;

    my ($pkg, $imports) = parse_file_meta($path, $raw);
    my $content = strip_go_source($raw);

    # derive import path from file location
    my $rel = $path;
    $rel =~ s{^\Q$repo\E/?}{};
    my $dir = dirname($rel);
    my $import_path = "$module/$dir";

    # Find func declarations - handle multiline receiver
    while ($content =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*[\(<{]/g) {
        my ($recv, $name) = ($1 // '', $2);
        next if $name eq 'init';  # init is special, called by runtime

        my $pos = pos($content) - length($name);
        my $line = 1 + ($raw =~ s/\A[^\n]*\n//g while length($raw) > 0 && $pos > 0); # wrong approach

        my $recv_type = '';
        if ($recv =~ /^\s*(?:\w+\s+)?(?:\*\s*)?([\w.]+)/) {
            $recv_type = $1;
        }

        my $sym_name;
        if ($recv_type ne '') {
            $sym_name = "(*$recv_type).$name";
        } else {
            $sym_name = $name;
        }

        my $key = "$import_path|$sym_name";
        $decls{$key} = {
            file => $path,
            pkg => $pkg,
            import_path => $import_path,
            name => $name,
            recv_type => $recv_type,
            sym_name => $sym_name,
            exported => ($name =~ /^[A-Z]/),
        };
    }
}

# Re-extract with line numbers properly
%decls = ();
for my $path (@all_go_files) {
    next unless $path =~ m{/internal/};
    open my $fh, '<', $path or die $!;
    my $raw = do { local $/; <$fh> };
    close $fh;

    my ($pkg, $imports) = parse_file_meta($path, $raw);
    my $content = strip_go_source($raw);

    my $rel = $path;
    $rel =~ s{^\Q$repo\E/?}{};
    my $dir = dirname($rel);
    my $import_path = "$module/$dir";

    my @lines = split /\n/, $content;
    my $accum = '';
    my $line_start = 1;
    for my $i (0..$#lines) {
        $accum .= $lines[$i] . "\n";
        # try to match complete func decl on accumulated (handle multiline receiver)
        while ($accum =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*[\(<{]/g) {
            my ($recv, $name) = ($1 // '', $2);
            next if $name eq 'init';
            my $recv_type = '';
            if ($recv =~ /^\s*(?:\w+\s+)?(?:\*\s*)?([\w.]+)/) {
                $recv_type = $1;
            }
            my $sym_name = $recv_type ne '' ? "(*$recv_type).$name" : $name;
            my $key = "$import_path|$sym_name";
            unless (exists $decls{$key}) {
                $decls{$key} = {
                    file => $path,
                    line => $i + 1,
                    pkg => $pkg,
                    import_path => $import_path,
                    name => $name,
                    recv_type => $recv_type,
                    sym_name => $sym_name,
                    exported => ($name =~ /^[A-Z]/),
                };
            }
        }
        # keep only last incomplete line if no semicolon ended func
        if (length($accum) > 2000) { $accum = $lines[$i] . "\n"; }
    }
}

# Better: scan full stripped content with offset->line mapping
%decls = ();
for my $path (@all_go_files) {
    next unless $path =~ m{/internal/};
    open my $fh, '<', $path or die $!;
    my $raw = do { local $/; <$fh> };
    close $fh;

    my ($pkg, $imports) = parse_file_meta($path, $raw);
    my $content = strip_go_source($raw);

    my $rel = $path;
    $rel =~ s{^\Q$repo\E/?}{};
    my $dir = dirname($rel);
    my $import_path = "$module/$dir";

    # Build line offsets
    my @line_starts = (0);
    for my $i (0..length($content)-1) {
        push @line_starts, $i + 1 if substr($content, $i, 1) eq "\n";
    }
    sub offset_to_line {
        my ($off) = @_;
        my $lo = 0; my $hi = $#line_starts;
        while ($lo < $hi) {
            my $mid = int(($lo + $hi + 1) / 2);
            if ($line_starts[$mid] <= $off) { $lo = $mid; } else { $hi = $mid - 1; }
        }
        return $lo + 1;
    }

    pos($content) = 0;
    while ($content =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*[\(<{]/g) {
        my ($recv, $name) = ($1 // '', $2);
        next if $name eq 'init';
        my $recv_type = '';
        if ($recv =~ /^\s*(?:\w+\s+)?(?:\*\s*)?([\w.]+)/) {
            $recv_type = $1;
        }
        my $sym_name = $recv_type ne '' ? "(*$recv_type).$name" : $name;
        my $key = "$import_path|$sym_name";
        my $off = pos($content) - length($name);
        $decls{$key} = {
            file => $path,
            line => offset_to_line($off),
            pkg => $pkg,
            import_path => $import_path,
            name => $name,
            recv_type => $recv_type,
            sym_name => $sym_name,
            exported => ($name =~ /^[A-Z]/),
        };
    }
}

print "Total internal declarations: " . scalar(keys %decls) . "\n";

# Build lookup: import_path|name -> key (for package-level funcs)
# Also: import_path|(*Type).Method
my %sym_lookup;
for my $key (keys %decls) {
    $sym_lookup{$key} = $key;
}

# --- find enclosing function for caller context ---
sub find_enclosing_func {
    my ($content, $pos) = @_;
    my $before = substr($content, 0, $pos);
    my $caller = 'toplevel';
    while ($before =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*[\(<{]/g) {
        $caller = $2;
        my $recv = $1 // '';
        if ($recv =~ /^\s*(?:\w+\s+)?(?:\*\s*)?([\w.]+)/) {
            $caller = "(*$1).$caller";
        }
    }
    return $caller;
}

# --- count call sites ---
# calls{$key} = [ { file, line, caller } ]
my %calls;

for my $path (@all_go_files) {
    open my $fh, '<', $path or die $!;
    my $raw = do { local $/; <$fh> };
    close $fh;

    my ($pkg, $imports) = parse_file_meta($path, $raw);
    my $content = strip_go_source($raw);

    my $rel = $path;
    $rel =~ s{^\Q$repo\E/?}{};
    my $dir = dirname($rel);
    my $local_import = "$module/$dir";

    # line offsets
    my @line_starts = (0);
    for my $i (0..length($content)-1) {
        push @line_starts, $i + 1 if substr($content, $i, 1) eq "\n";
    }
    my $offset_to_line = sub {
        my ($off) = @_;
        my $lo = 0; my $hi = $#line_starts;
        while ($lo < $hi) {
            my $mid = int(($lo + $hi + 1) / 2);
            if ($line_starts[$mid] <= $off) { $lo = $mid; } else { $hi = $mid - 1; }
        }
        return $lo + 1;
    };

    # Skip declarations: mark func body ranges? Simpler: match calls only outside func keyword decl pattern
    # Pattern for calls:
    # 1. qualified: alias.FuncName(
    # 2. unqualified: FuncName(
    # 3. method: expr.MethodName(

    pos($content) = 0;
    while ($content =~ /(?<![\w.])(\w+)\.(\w+)\s*\(/g) {
        my ($alias, $fname) = ($1, $2);
        next if $alias eq 'return' || $alias eq 'case' || $alias eq 'switch';
        my $off = pos($content) - length("$alias.$fname");
        my $line = $offset_to_line->($off);
        my $caller = find_enclosing_func($content, $off);
        my $caller_id = "$path:$caller";

        my $import_path = $imports->{$alias};
        if ($import_path && $import_path =~ m{/internal/}) {
            my $key = "$import_path|$fname";
            # also try as method - less common for qualified package calls
            if (exists $decls{$key}) {
                push @{$calls{$key}}, { file => $path, line => $line, caller => $caller_id };
            }
        }
    }

    # method calls: recv.Method(
    pos($content) = 0;
    while ($content =~ /(?<![\w.])([\w\)\]]+)\.(\w+)\s*\(/g) {
        my ($recv_expr, $mname) = ($1, $2);
        next if $recv_expr =~ /^(return|case|switch|else|if|for|go|defer)$/;
        my $off = pos($content) - length("$recv_expr.$mname");
        my $line = $offset_to_line->($off);
        my $caller = find_enclosing_func($content, $off);
        my $caller_id = "$path:$caller";

        # If same package internal file, try to match any receiver type with this method
        if ($path =~ m{/internal/}) {
            for my $key (keys %decls) {
                next unless $decls{$key}{import_path} eq $local_import;
                next unless $decls{$key}{name} eq $mname;
                next unless $decls{$key}{recv_type} ne '';
                push @{$calls{$key}}, { file => $path, line => $line, caller => $caller_id };
            }
        }
        # Cross-package: hard to resolve receiver type statically - skip unless we can infer from constructor patterns
    }

    # unqualified function calls in same package (internal only callers in internal pkg)
    if ($path =~ m{/internal/}) {
        pos($content) = 0;
        while ($content =~ /(?<![\w.])(\w+)\s*\(/g) {
            my ($fname) = $1;
            next if $fname =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|delete|copy|close|panic|recover|print|println|complex|real|imag|map|chan|struct|interface|select|range|case|default)$/;
            my $off = pos($content) - length($fname);
            # skip if this is a func declaration
            my $ctx = substr($content, max(0,$off-10), 20);
            next if $ctx =~ /\bfunc\s+\Q$fname\E\s*[\(<{]/;

            my $line = $offset_to_line->($off);
            my $caller = find_enclosing_func($content, $off);
            my $caller_id = "$path:$caller";

            my $key = "$local_import|$fname";
            if (exists $decls{$key} && $decls{$key}{recv_type} eq '') {
                push @{$calls{$key}}, { file => $path, line => $line, caller => $caller_id };
            }
        }
    }
}

sub max { $_[0] > $_[1] ? $_[0] : $_[1] }

# Deduplicate call sites by file:line
my %fanin;
for my $key (keys %decls) {
    my @sites = @{$calls{$key} // []};
    my %unique_sites;
    my %unique_callers;
    for my $s (@sites) {
        $unique_sites{"$s->{file}:$s->{line}"} = 1;
        $unique_callers{$s->{caller}} = 1;
    }
    $fanin{$key} = {
        call_sites => scalar(keys %unique_sites),
        distinct_callers => scalar(keys %unique_callers),
        decl => $decls{$key},
    };
}

# Sort by call_sites
my @sorted = sort { $fanin{$b}{call_sites} <=> $fanin{$a}{call_sites} || $fanin{$b}{distinct_callers} <=> $fanin{$a}{distinct_callers} } keys %fanin;

print "\nTop 30 by call site count:\n";
for my $i (0..29) {
    last unless $i < @sorted;
    my $k = $sorted[$i];
    my $f = $fanin{$k};
  my $d = $f->{decl};
  printf "%4d sites, %3d callers | %s | %s:%d\n",
    $f->{call_sites}, $f->{distinct_callers},
    $d->{sym_name}, $d->{file}, $d->{line};
}

print "\n=== WINNER ===\n";
my $top = $sorted[0];
my $f = $fanin{$top};
my $d = $f->{decl};
print "Symbol: $d->{sym_name}\n";
print "Import path: $d->{import_path}\n";
print "File: $d->{file}:$d->{line}\n";
print "Call sites: $f->{call_sites}\n";
print "Distinct callers: $f->{distinct_callers}\n";

