#!/usr/bin/perl
use strict;
use warnings;

my $repo = '/bench/repo';
my $module = 'github.com/usememos/memos';

my @all_go_files = split /\n/, `find '$repo' -name '*.go' ! -path '*/vendor/*' ! -path '*/proto/gen/*' 2>/dev/null`;
chomp @all_go_files;

sub strip_go_source {
    my ($src) = @_;
    my $out = '';
    my $i = 0;
    my $len = length($src);
    while ($i < $len) {
        if (substr($src, $i, 2) eq '//') {
            while ($i < $len && substr($src, $i, 1) ne "\n") { $i++; }
            next;
        }
        if (substr($src, $i, 2) eq '/*') {
            $i += 2;
            while ($i < $len - 1 && substr($src, $i, 2) ne '*/') { $i++; }
            $i += 2 if $i < $len - 1;
            next;
        }
        if (substr($src, $i, 1) eq '`') {
            $out .= '`'; $i++;
            while ($i < $len && substr($src, $i, 1) ne '`') { $i++; }
            $out .= '`' if $i < $len; $i++ if $i < $len;
            next;
        }
        if (substr($src, $i, 1) eq '"') {
            $out .= '"'; $i++;
            while ($i < $len) {
                my $c = substr($src, $i, 1);
                if ($c eq '\\') { $out .= $c; $i++; $out .= substr($src, $i, 1) if $i < $len; $i++; next; }
                $out .= $c; $i++; last if $c eq '"';
            }
            next;
        }
        if (substr($src, $i, 1) eq "'") {
            $out .= "'"; $i++;
            while ($i < $len) {
                my $c = substr($src, $i, 1);
                if ($c eq '\\') { $out .= $c; $i++; $out .= substr($src, $i, 1) if $i < $len; $i++; next; }
                $out .= $c; $i++; last if $c eq "'";
            }
            next;
        }
        $out .= substr($src, $i, 1);
        $i++;
    }
    return $out;
}

sub file_import_path {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s{^\Q$repo\E/?}{};
    my $dir = $rel;
    $dir =~ s{/[^/]+$}{};
    return $dir eq $rel ? $module : "$module/$dir";
}

sub parse_file_meta {
    my ($content) = @_;
    my $pkg = '';
    my %imports;
    $pkg = $1 if $content =~ /^package\s+(\w+)/m;
    while ($content =~ /\bimport\s+"([^"]+)"/g) {
        my $p = $1;
        my $alias = $p; $alias =~ s{.*/}{};
        $imports{$alias} = $p;
    }
    while ($content =~ /\bimport\s*\((.*?)\)/gs) {
        for my $line (split /\n/, $1) {
            $line =~ s{//.*}{};
            next if $line =~ /^\s*$/;
            if ($line =~ /^\s*(?:(\w+)\s+)?"([^"]+)"/) {
                my ($alias, $path) = ($1, $2);
                $alias //= $path; $alias =~ s{.*/}{};
                $imports{$alias} = $path;
            }
        }
    }
    return ($pkg, \%imports);
}

sub build_line_starts {
    my ($content) = @_;
    my @starts = (0);
    for my $i (0..length($content)-1) {
        push @starts, $i + 1 if substr($content, $i, 1) eq "\n";
    }
    return \@starts;
}

sub offset_to_line {
    my ($starts, $off) = @_;
    my $lo = 0; my $hi = $#$starts;
    while ($lo < $hi) {
        my $mid = int(($lo + $hi + 1) / 2);
        if ($starts->[$mid] <= $off) { $lo = $mid; } else { $hi = $mid - 1; }
    }
    return $lo + 1;
}

sub find_enclosing_func {
    my ($content, $pos) = @_;
    my $before = substr($content, 0, $pos);
    my $caller = 'toplevel';
    while ($before =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*[\(<{]/g) {
        $caller = $2;
        my $recv = $1 // '';
        if ($recv =~ /^\s*(?:\w+\s+)?(?:\*\s*)?([\w.]+)/) {
            $caller = "(*$1).$caller";
        }
    }
    return $caller;
}

sub is_func_decl_at {
    my ($content, $off, $name) = @_;
    my $start = $off > 30 ? $off - 30 : 0;
    my $ctx = substr($content, $start, $off - $start + length($name) + 5);
    return $ctx =~ /\bfunc\s+(?:\([^)]*\)\s+)?\Q$name\E\s*[\(<{]/;
}

# --- declarations ---
my %decls;
for my $path (@all_go_files) {
    next unless $path =~ m{/internal/};
    open my $fh, '<', $path or die $!;
    my $raw = do { local $/; <$fh> }; close $fh;
    my ($pkg, $imports) = parse_file_meta($raw);
    my $content = strip_go_source($raw);
    my $import_path = file_import_path($path);
    my $starts = build_line_starts($content);

    pos($content) = 0;
    while ($content =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*[\(<{]/g) {
        my ($recv, $name) = ($1 // '', $2);
        next if $name eq 'init';
        my $recv_type = '';
        if ($recv =~ /^\s*(?:\w+\s+)?(?:\*\s*)?([\w.]+)/) { $recv_type = $1; }
        my $sym_name = $recv_type ne '' ? "(*$recv_type).$name" : $name;
        my $key = "$import_path|$sym_name";
        my $off = pos($content) - length($name);
        $decls{$key} = {
            file => $path, line => offset_to_line($starts, $off),
            pkg => $pkg, import_path => $import_path,
            name => $name, recv_type => $recv_type, sym_name => $sym_name,
        };
    }
}
print "Declarations in internal/: " . scalar(keys %decls) . "\n";

# Index methods by import_path|MethodName for ambiguous resolution
my %methods_by_name;
for my $key (keys %decls) {
    my $d = $decls{$key};
    next unless $d->{recv_type} ne '';
    push @{$methods_by_name{"$d->{import_path}|$d->{name}"}}, $key;
}

# Index package funcs
my %funcs_by_key;
for my $key (keys %decls) {
    next unless $decls{$key}{recv_type} eq '';
    $funcs_by_key{$key} = 1;
}

my %calls;
my @keywords = map { $_ => 1 } qw(if for switch return func go defer make new len cap append delete copy close panic recover print println complex real imag map chan struct interface select range case default);

for my $path (@all_go_files) {
    open my $fh, '<', $path or die $!;
    my $raw = do { local $/; <$fh> }; close $fh;
    my ($pkg, $imports) = parse_file_meta($raw);
    my $content = strip_go_source($raw);
    my $local_import = file_import_path($path);
    my $starts = build_line_starts($content);

    my $record = sub {
        my ($key, $off) = @_;
        return unless exists $decls{$key};
        my $line = offset_to_line($starts, $off);
        my $caller = find_enclosing_func($content, $off);
        push @{$calls{$key}}, { file => $path, line => $line, caller => "$path:$caller" };
    };

    # Qualified package calls: alias.Func(
    pos($content) = 0;
    while ($content =~ /(?<![\w.])(\w+)\.(\w+)\s*\(/g) {
        my ($alias, $fname) = ($1, $2);
        next if $keywords{$alias};
        my $off = pos($content) - length("$alias.$fname");
        my $import_path = $imports->{$alias};
        next unless $import_path && $import_path =~ m{/internal/};
        my $key = "$import_path|$fname";
        $record->($key, $off) if exists $funcs_by_key{$key};
    }

    # Same-package unqualified calls (only when caller is in same internal package)
    if ($path =~ m{/internal/}) {
        pos($content) = 0;
        while ($content =~ /(?<![\w.])(\w+)\s*\(/g) {
            my ($fname) = $1;
            next if $keywords{$fname};
            my $off = pos($content) - length($fname);
            next if is_func_decl_at($content, $off, $fname);
            my $key = "$local_import|$fname";
            $record->($key, $off) if exists $funcs_by_key{$key};
        }
    }

    # Method calls - same package only (conservative cross-pkg would over-count)
    if ($path =~ m{/internal/}) {
        pos($content) = 0;
        while ($content =~ /(?<![\w.])([\w\)\]]+)\.(\w+)\s*\(/g) {
            my ($recv_expr, $mname) = ($1, $2);
            next if $keywords{$recv_expr};
            my $off = pos($content) - length("$recv_expr.$mname");
            my $mbkey = "$local_import|$mname";
            next unless exists $methods_by_name{$mbkey};
            for my $key (@{$methods_by_name{$mbkey}}) {
                $record->($key, $off);
            }
        }
    }
}

my %fanin;
for my $key (keys %decls) {
    my %sites; my %callers;
    for my $s (@{$calls{$key} // []}) {
        $sites{"$s->{file}:$s->{line}"} = 1;
        $callers{$s->{caller}} = 1;
    }
    $fanin{$key} = { sites => scalar(keys %sites), callers => scalar(keys %callers), decl => $decls{$key} };
}

my @sorted = sort { $fanin{$b}{sites} <=> $fanin{$a}{sites} || $fanin{$b}{callers} <=> $fanin{$a}{callers} } keys %fanin;

print "\nTop 40 symbols by static call-site fan-in:\n";
for my $i (0..39) {
    last unless $i < @sorted;
    my $k = $sorted[$i]; my $f = $fanin{$k}; my $d = $f->{decl};
    printf "%4d sites | %3d callers | %-40s | %s:%d\n", $f->{sites}, $f->{callers}, $d->{sym_name}, $d->{file}, $d->{line};
}

print "\n=== TOP RESULT ===\n";
my $top = $sorted[0]; my $f = $fanin{$top}; my $d = $f->{decl};
print "sym=$d->{sym_name}\npath=$d->{import_path}\nfile=$d->{file}:$d->{line}\nsites=$f->{sites}\ncallers=$f->{callers}\n";

