    my $len = length($src);
    while ($i < $len) {
        if (substr($src, $i, 2) eq '//') {
            while ($i < $len && substr($src, $i, 1) ne "\n") { $i++; }
            next;
        }
        if (substr($src, $i, 2) eq '/*') {
            $i += 2;
            while ($i < $len - 1 && substr($src, $i, 2) ne '*/') { $i++; }
            $i += 2 if $i < $len - 1;
            next;
        }
        if (substr($src, $i, 1) eq '`') {
            $out .= '`'; $i++;
            while ($i < $len && substr($src, $i, 1) ne '`') { $i++; }
            $out .= '`' if $i < $len; $i++ if $i < $len;
            next;
        }
        if (substr($src, $i, 1) eq '"') {
            $out .= '"'; $i++;
            while ($i < $len) {
                my $c = substr($src, $i, 1);
                if ($c eq '\\') { $out .= $c; $i++; $out .= substr($src, $i, 1) if $i < $len; $i++; next; }
                $out .= $c; $i++; last if $c eq '"';
            }
            next;
        }
        if (substr($src, $i, 1) eq "'") {
            $out .= "'"; $i++;
            while ($i < $len) {
                my $c = substr($src, $i, 1);
                if ($c eq '\\') { $out .= $c; $i++; $out .= substr($src, $i, 1) if $i < $len; $i++; next; }
                $out .= $c; $i++; last if $c eq "'";
            }
            next;
        }
        $out .= substr($src, $i, 1);
        $i++;
    }
    return $out;
}

sub file_import_path {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s{^\Q$repo\E/?}{};
    my $dir = $rel;
    $dir =~ s{/[^/]+$}{};
    return $dir eq $rel ? $module : "$module/$dir";
}

sub parse_file_meta {
    my ($content) = @_;
    my $pkg = '';
    my %imports;
    $pkg = $1 if $content =~ /^package\s+(\w+)/m;
    while ($content =~ /\bimport\s+"([^"]+)"/g) {
        my $p = $1;
        my $alias = $p; $alias =~ s{.*/}{};
        $imports{$alias} = $p;
    }
    while ($content =~ /\bimport\s*\((.*?)\)/gs) {
        for my $line (split /\n/, $1) {
            $line =~ s{//.*}{};
            next if $line =~ /^\s*$/;
            if ($line =~ /^\s*(?:(\w+)\s+)?"([^"]+)"/) {
                my ($alias, $path) = ($1, $2);
                $alias //= $path; $alias =~ s{.*/}{};
                $imports{$alias} = $path;
            }
        }
    }
