}

sub build_line_starts {
    my ($content) = @_;
    my @starts = (0);
    for my $i (0..length($content)-1) {
        push @starts, $i + 1 if substr($content, $i, 1) eq "\n";
    }
    return \@starts;
}

sub offset_to_line {
    my ($starts, $off) = @_;
    my $lo = 0; my $hi = $#$starts;
    while ($lo < $hi) {
        my $mid = int(($lo + $hi + 1) / 2);
        if ($starts->[$mid] <= $off) { $lo = $mid; } else { $hi = $mid - 1; }
