    my ($content, $pos) = @_;
    my $before = substr($content, 0, $pos);
    my $caller = 'toplevel';
    while ($before =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*[\(<{]/g) {
        $caller = $2;
        my $recv = $1 // '';
        if ($recv =~ /^\s*(?:\w+\s+)?(?:\*\s*)?([\w.]+)/) {
