        my $key = "$import_path|$sym_name";
        my $off = pos($content) - length($name);
        $decls{$key} = {
            file => $path, line => offset_to_line($starts, $off),
            pkg => $pkg, import_path => $import_path,
            name => $name, recv_type => $recv_type, sym_name => $sym_name,
        };
    }
}
print "Declarations in internal/: " . scalar(keys %decls) . "\n";

# Index methods by import_path|MethodName for ambiguous resolution
my %methods_by_name;
for my $key (keys %decls) {
    my $d = $decls{$key};
    next unless $d->{recv_type} ne '';
    push @{$methods_by_name{"$d->{import_path}|$d->{name}"}}, $key;
}

# Index package funcs
my %funcs_by_key;
for my $key (keys %decls) {
    next unless $decls{$key}{recv_type} eq '';
    $funcs_by_key{$key} = 1;
}

my %calls;
my @keywords = map { $_ => 1 } qw(if for switch return func go defer make new len cap append delete copy close panic recover print println complex real imag map chan struct interface select range case default);

for my $path (@all_go_files) {
    open my $fh, '<', $path or die $!;
    my $raw = do { local $/; <$fh> }; close $fh;
    my ($pkg, $imports) = parse_file_meta($raw);
    my $content = strip_go_source($raw);
    my $local_import = file_import_path($path);
    my $starts = build_line_starts($content);

    my $record = sub {
        my ($key, $off) = @_;
        return unless exists $decls{$key};
        my $line = offset_to_line($starts, $off);
        my $caller = find_enclosing_func($content, $off);
        push @{$calls{$key}}, { file => $path, line => $line, caller => "$path:$caller" };
    };

    # Qualified package calls: alias.Func(
    pos($content) = 0;
    while ($content =~ /(?<![\w.])(\w+)\.(\w+)\s*\(/g) {
        my ($alias, $fname) = ($1, $2);
        next if $keywords{$alias};
        my $off = pos($content) - length("$alias.$fname");
        my $import_path = $imports->{$alias};
        next unless $import_path && $import_path =~ m{/internal/};
        my $key = "$import_path|$fname";
        $record->($key, $off) if exists $funcs_by_key{$key};
    }

    # Same-package unqualified calls (only when caller is in same internal package)
    if ($path =~ m{/internal/}) {
        pos($content) = 0;
        while ($content =~ /(?<![\w.])(\w+)\s*\(/g) {
            my ($fname) = $1;
            next if $keywords{$fname};
            my $off = pos($content) - length($fname);
            next if is_func_decl_at($content, $off, $fname);
            my $key = "$local_import|$fname";
            $record->($key, $off) if exists $funcs_by_key{$key};
        }
    }

