    if ($path =~ m{/internal/}) {
        pos($content) = 0;
        while ($content =~ /(?<![\w.])([\w\)\]]+)\.(\w+)\s*\(/g) {
            my ($recv_expr, $mname) = ($1, $2);
            next if $keywords{$recv_expr};
            my $off = pos($content) - length("$recv_expr.$mname");
            my $mbkey = "$local_import|$mname";
            next unless exists $methods_by_name{$mbkey};
            for my $key (@{$methods_by_name{$mbkey}}) {
                $record->($key, $off);
            }
        }
    }
