my %fanin;
for my $key (keys %decls) {
    my %sites; my %callers;
    for my $s (@{$calls{$key} // []}) {
        $sites{"$s->{file}:$s->{line}"} = 1;
        $callers{$s->{caller}} = 1;
    }
    $fanin{$key} = { sites => scalar(keys %sites), callers => scalar(keys %callers), decl => $decls{$key} };
}

my @sorted = sort { $fanin{$b}{sites} <=> $fanin{$a}{sites} || $fanin{$b}{callers} <=> $fanin{$a}{callers} } keys %fanin;

print "\nTop 40 symbols by static call-site fan-in:\n";
for my $i (0..39) {
    last unless $i < @sorted;
    my $k = $sorted[$i]; my $f = $fanin{$k}; my $d = $f->{decl};
    printf "%4d sites | %3d callers | %-40s | %s:%d\n", $f->{sites}, $f->{callers}, $d->{sym_name}, $d->{file}, $d->{line};
}

print "\n=== TOP RESULT ===\n";
my $top = $sorted[0]; my $f = $fanin{$top}; my $d = $f->{decl};
print "sym=$d->{sym_name}\npath=$d->{import_path}\nfile=$d->{file}:$d->{line}\nsites=$f->{sites}\ncallers=$f->{callers}\n";

