            while ($i < $len - 1 && substr($src, $i, 2) ne '*/') { $i++; }
            $i += 2 if $i < $len - 1;
            next;
        }
        if (substr($src, $i, 1) eq '`') {
            $out .= '`'; $i++;
            while ($i < $len && substr($src, $i, 1) ne '`') { $i++; }
            $out .= '`' if $i < $len; $i++ if $i < $len;
            next;
        }
        if (substr($src, $i, 1) eq '"') {
            $out .= '"'; $i++;
            while ($i < $len) {
                my $c = substr($src, $i, 1);
                if ($c eq '\\') { $out .= $c; $i++; $out .= substr($src, $i, 1) if $i < $len; $i++; next; }
                $out .= $c; $i++; last if $c eq '"';
            }
            next;
        }
        if (substr($src, $i, 1) eq "'") {
            $out .= "'"; $i++;
            while ($i < $len) {
                my $c = substr($src, $i, 1);
                if ($c eq '\\') { $out .= $c; $i++; $out .= substr($src, $i, 1) if $i < $len; $i++; next; }
                $out .= $c; $i++; last if $c eq "'";
            }
            next;
        }
        $out .= substr($src, $i, 1);
        $i++;
    }
    return $out;
}

sub file_import_path {
    my ($path) = @_;
    my $rel = $path; $rel =~ s{^\Q$repo\E/?}{};
    my $dir = $rel; $dir =~ s{/[^/]+$}{};
    return $dir eq $rel ? $module : "$module/$dir";
}

sub parse_file_meta {
    my ($content) = @_;
    my $pkg = '';
    my %imports;
    $pkg = $1 if $content =~ /^package\s+(\w+)/m;
    while ($content =~ /\bimport\s+"([^"]+)"/g) {
        my $p = $1; my $alias = $p; $alias =~ s{.*/}{};
        $imports{$alias} = $p;
    }
    while ($content =~ /\bimport\s*\((.*?)\)/gs) {
        for my $line (split /\n/, $1) {
            $line =~ s{//.*}{};
            next if $line =~ /^\s*$/;
            if ($line =~ /^\s*(?:(\w+)\s+)?"([^"]+)"/) {
                my ($alias, $path) = ($1, $2);
                $alias //= $path; $alias =~ s{.*/}{};
                $imports{$alias} = $path;
            }
        }
    }
    return ($pkg, \%imports);
}

sub build_line_starts {
    my ($content) = @_;
    my @starts = (0);
    for my $i (0..length($content)-1) { push @starts, $i + 1 if substr($content, $i, 1) eq "\n"; }
    return \@starts;
}

sub offset_to_line {
    my ($starts, $off) = @_;
    my $lo = 0; my $hi = $#$starts;
    while ($lo < $hi) {
        my $mid = int(($lo + $hi + 1) / 2);
        if ($starts->[$mid] <= $off) { $lo = $mid; } else { $hi = $mid - 1; }
    }
    return $lo + 1;
}

sub find_enclosing_func {
    my ($content, $pos) = @_;
    my $before = substr($content, 0, $pos);
    my $caller = 'toplevel';
    while ($before =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*[\(<{]/g) {
        $caller = $2;
        my $recv = $1 // '';
        if ($recv =~ /^\s*(?:\w+\s+)?(?:\*\s*)?([\w.]+)/) { $caller = "(*$1).$caller"; }
    }
    return $caller;
}

sub is_func_decl_at {
    my ($content, $off, $name) = @_;
    my $start = $off > 40 ? $off - 40 : 0;
    my $ctx = substr($content, $start, $off - $start + length($name) + 8);
    return $ctx =~ /\bfunc\s+(?:\([^)]*\)\s+)?\Q$name\E\s*[\(<{]/;
}

my %keywords = map { $_ => 1 } qw(if for switch return func go defer make new len cap append delete copy close panic recover print println complex real imag map chan struct interface select range case default);

# --- declarations in internal/ ---
my %decls;
for my $path (@all_go_files) {
    next unless $path =~ m{/internal/};
    open my $fh, '<', $path or die $!;
    my $raw = do { local $/; <$fh> }; close $fh;
    my $content = strip_go_source($raw);
    my $import_path = file_import_path($path);
    my $starts = build_line_starts($content);
    pos($content) = 0;
    while ($content =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*[\(<{]/g) {
        my ($recv, $name) = ($1 // '', $2);
        next if $name eq 'init';
        my $recv_type = '';
        if ($recv =~ /^\s*(?:\w+\s+)?(?:\*\s*)?([\w.]+)/) { $recv_type = $1; }
        my $sym_name = $recv_type ne '' ? "(*$recv_type).$name" : $name;
        my $key = "$import_path|$sym_name";
        my $off = pos($content) - length($name);
        $decls{$key} = {
            file => $path, line => offset_to_line($starts, $off),
            import_path => $import_path, name => $name, recv_type => $recv_type, sym_name => $sym_name,
        };
    }
}

my %funcs_by_key;
my %methods_by_pkg_name;  # import_path|MethodName -> [keys]
for my $key (keys %decls) {
    my $d = $decls{$key};
    if ($d->{recv_type} eq '') {
        $funcs_by_key{$key} = 1;
    } else {
        push @{$methods_by_pkg_name{"$d->{import_path}|$d->{name}"}}, $key;
    }
}

# imported internal packages per file
my %file_internal_imports;  # path -> [import_paths]
for my $path (@all_go_files) {
    open my $fh, '<', $path or die $!;
    my $raw = do { local $/; <$fh> }; close $fh;
    my ($pkg, $imports) = parse_file_meta($raw);
    my @internal;
    for my $alias (keys %$imports) {
        push @internal, $imports->{$alias} if $imports->{$alias} =~ m{/internal/};
    }
    $file_internal_imports{$path} = \@internal;
}

my %calls;
for my $path (@all_go_files) {
    open my $fh, '<', $path or die $!;
    my $raw = do { local $/; <$fh> }; close $fh;
    my ($pkg, $imports) = parse_file_meta($raw);
    my $content = strip_go_source($raw);
    my $local_import = file_import_path($path);
    my $starts = build_line_starts($content);
    my $internal_imports = $file_internal_imports{$path};

    my $record = sub {
        my ($key, $off) = @_;
        return unless exists $decls{$key};
        my $line = offset_to_line($starts, $off);
        my $caller = find_enclosing_func($content, $off);
        push @{$calls{$key}}, { file => $path, line => $line, caller => "$path:$caller" };
    };

    # Qualified package-level: alias.Func(
    pos($content) = 0;
    while ($content =~ /(?<![\w.])(\w+)\.(\w+)\s*\(/g) {
        my ($alias, $fname) = ($1, $2);
        next if $keywords{$alias};
        my $off = pos($content) - length("$alias.$fname");
        my $import_path = $imports->{$alias};
        next unless $import_path && $import_path =~ m{/internal/};
        my $key = "$import_path|$fname";
        $record->($key, $off) if exists $funcs_by_key{$key};
    }

    # Same-package unqualified func calls
    if ($path =~ m{/internal/}) {
        pos($content) = 0;
        while ($content =~ /(?<![\w.])(\w+)\s*\(/g) {
            my ($fname) = $1;
            next if $keywords{$fname};
            my $off = pos($content) - length($fname);
            next if is_func_decl_at($content, $off, $fname);
            my $key = "$local_import|$fname";
            $record->($key, $off) if exists $funcs_by_key{$key};
        }
    }

    # Method calls: recv.Method(
    pos($content) = 0;
    while ($content =~ /(?<![\w.])([\w\)\]]+)\.(\w+)\s*\(/g) {
        my ($recv_expr, $mname) = ($1, $2);
        next if $keywords{$recv_expr};
        my $off = pos($content) - length("$recv_expr.$mname");
        next if is_func_decl_at($content, $off, $mname);

        my @candidate_pkgs;
        if ($path =~ m{/internal/}) {
            push @candidate_pkgs, $local_import;
        }
        push @candidate_pkgs, @$internal_imports;

        my %seen;
        for my $ip (@candidate_pkgs) {
            next if $seen{$ip}++;
            my $mbkey = "$ip|$mname";
            next unless exists $methods_by_pkg_name{$mbkey};
            for my $key (@{$methods_by_pkg_name{$mbkey}}) {
                $record->($key, $off);
            }
        }
    }
}

my %fanin;
for my $key (keys %decls) {
    my (%sites, %callers);
    for my $s (@{$calls{$key} // []}) {
        $sites{"$s->{file}:$s->{line}"} = 1;
        $callers{$s->{caller}} = 1;
    }
    $fanin{$key} = { sites => scalar(keys %sites), callers => scalar(keys %callers), decl => $decls{$key} };
}

my @sorted = sort { $fanin{$b}{sites} <=> $fanin{$a}{sites} || $fanin{$b}{callers} <=> $fanin{$a}{callers} } keys %fanin;

print "Declarations: " . scalar(keys %decls) . "\n\nTop 25:\n";
for my $i (0..24) {
    last unless $i < @sorted;
    my $k = $sorted[$i]; my $f = $fanin{$k}; my $d = $f->{decl};
    printf "%4d sites | %3d callers | %-45s | %s:%d\n", $f->{sites}, $f->{callers}, $d->{sym_name}, $d->{file}, $d->{line};
}

my $top = $sorted[0]; my $f = $fanin{$top}; my $d = $f->{decl};
print "\nWINNER: $d->{sym_name} @ $d->{file}:$d->{line}\n";
print "import_path=$d->{import_path}\ncall_sites=$f->{sites}\ndistinct_callers=$f->{callers}\n";

# Sanity check top 3 with declaration subtraction
for my $k (@sorted[0..4]) {
    my $name = $decls{$k}{name};
    my $recv = $decls{$k}{recv_type};
    my $grep_pat = $recv ? "\\.$name\\s*\\(" : "\\b$name\\s*\\(";
    my $grep_out = `grep -rnE '$grep_pat' '$repo' --include='*.go' 2>/dev/null | grep -v '/proto/gen/' | grep -v vendor`;
    my @lines = split /\n/, $grep_out;
    chomp @lines; @lines = grep { $_ ne '' } @lines;
    my $decls_in_grep = 0;
    for (@lines) { $decls_in_grep++ if /\bfunc\b/; }
    printf "grep sanity %s: raw=%d decl=%d approx_calls=%d script=%d\n",
        $decls{$k}{sym_name}, scalar(@lines), $decls_in_grep, scalar(@lines)-$decls_in_grep, $fanin{$k}{sites};
}

