# Count unique caller functions for CompileToStatement
perl -e '
my %callers;
open F, "-|", "grep", "-rn", "CompileToStatement", "/bench/repo", "--include=*.go" or die;
while (<F>) {
  next if /proto\/gen/ || /vendor/;
  next unless /\.CompileToStatement\s*\(/ || (/CompileToStatement\s*\(/ && !/^\s*\/\// && !/func \(e \*Engine\) CompileToStatement/);
  next if /func \(e \*Engine\) CompileToStatement/;
  next if /\/\/ CompileToStatement/;
  if (m{^(/bench/repo/[^:]+):(\d+):}) {
    push @{$files{$1}}, $2;
  }
}
# count distinct enclosing - use file:line as proxy for call site (38)
my $sites=0; for (values %files) { $sites += @$_ }
print "call sites by file:line: $sites\n";
'

